        switch (child)
        {
            case TableListListItem children:
                Children ??= [];
                if (!Children.Contains(children))
                {
                    Children = [..Children, children];
                    ModifiedParameters[nameof(Children)] = Children;
                }
                
                return true;
            case TableListItemPanelWidget panel:
                if (panel != Panel)
                {
                    Panel = panel;
                    ModifiedParameters[nameof(Panel)] = Panel;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case TableListListItem children:
                Children = Children?.Where(c => c != children).ToList();
                ModifiedParameters[nameof(Children)] = Children;
                return true;
            case TableListItemPanelWidget _:
                Panel = null;
                ModifiedParameters[nameof(Panel)] = Panel;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Children is not null)
        {
            foreach (TableListListItem child in Children)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        Panel?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
}
